-- SlumsMS 055 (owner 2026-10-29): drop tables for the six mobs that kill and drop but sat outside 050's three regions
-- (not placed on any map: Cygnus' four knights, Castellan, the Arcane Lantern Erda). Same rules as 050
-- (docs/economy/bb-drops/RULES.md): tier by boss flag and HP, outclassing gear rare, conservative boss tables; Castellan
-- (Ninja Castle) draws from the classic pool only. Generated by tools/economy/gen_bb_drops.py gaps; edit the
-- generator, not this file. 172 rows for 6 mobs:
--   8641008 Lantern Erda (lv 200, normal, arcane): 24 rows
--   8850006 Oz (lv 188, boss, future): 30 rows
--   8850007 Irena (lv 188, boss, future): 30 rows
--   8850008 Eckhart (lv 188, boss, future): 30 rows
--   8850009 Hawkeye (lv 188, boss, future): 30 rows
--   9400408 Castellan (lv 180, elite, zipangu): 28 rows
-- The phase/form stubs 8850005, 8850011, 8880150, 8880302, 8880415, 8645009, 8641009 stay dropless.
-- An existing (mob, item) pair (the Lantern Erda's Monster Book card) is skipped. Only rows this migration really
-- inserts are recorded in boss_drops_055_rows, so the rollback deletes exactly those. Applying it twice changes nothing
-- (ledger id '055-boss-drop-gaps'). A running server reads drop_data on boot or on !reloaddrops.
CREATE TABLE IF NOT EXISTS mapleroot_integration_migrations (
  migration_id varchar(100) PRIMARY KEY,
  applied_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS boss_drops_055_rows (
  dropperid int NOT NULL,
  itemid    int NOT NULL,
  PRIMARY KEY (dropperid, itemid)
) ENGINE=InnoDB;

CREATE TEMPORARY TABLE boss_drops_055_new (
  dropperid int NOT NULL, itemid int NOT NULL, minimum_quantity int NOT NULL, maximum_quantity int NOT NULL,
  questid int NOT NULL, chance int NOT NULL, PRIMARY KEY (dropperid, itemid));

-- record only the pairs not already in drop_data (once recorded, a pair stays recorded on a second run)
SELECT n.dropperid, n.itemid FROM boss_drops_055_new n
 WHERE NOT EXISTS (SELECT 1 FROM drop_data d WHERE d.dropperid = n.dropperid AND d.itemid = n.itemid);
SELECT n.dropperid, n.itemid, n.minimum_quantity, n.maximum_quantity, n.questid, n.chance
  FROM boss_drops_055_new n JOIN boss_drops_055_rows r ON r.dropperid = n.dropperid AND r.itemid = n.itemid
 WHERE NOT EXISTS (SELECT 1 FROM drop_data d WHERE d.dropperid = n.dropperid AND d.itemid = n.itemid);

DROP TEMPORARY TABLE boss_drops_055_new;
